-- O(log n) lookup instead of scanning 10M rows
CREATE INDEX idx_orders_customer ON orders(customer_id);

-- Composite: serves (last_name) and (last_name, first_name), NOT (first_name) alone
CREATE INDEX idx_users_name ON users(last_name, first_name);

-- Covering: answers the query from the index alone
CREATE INDEX idx_orders_cover
  ON orders(customer_id) INCLUDE (total_cents, placed_at);
